class Solution {
  public int maxPointsInsideSquare(int[][] points, String s) {
    int[] smallest = new int[26], second = new int[26];
    Arrays.fill(smallest, Integer.MAX_VALUE);
    Arrays.fill(second, Integer.MAX_VALUE);
    int[] dist = new int[points.length];
    for (int i = 0; i < points.length; i++) {
      int d = Math.max(Math.abs(points[i][0]), Math.abs(points[i][1])), c = s.charAt(i) - 'a';
      dist[i] = d;
      if (d < smallest[c]) {
        second[c] = smallest[c];
        smallest[c] = d;
      } else if (d < second[c]) {
        second[c] = d;
      }
    }
    // the square must stop before the second occurrence of any tag
    int limit = Integer.MAX_VALUE;
    for (int c = 0; c < 26; c++) limit = Math.min(limit, second[c]);
    int count = 0;
    for (int d : dist) if (d < limit) count++;
    return count;
  }
}
